import struct
import sys

# Read file as binary
def extract_floats(filename, width=4):
    floats = []
    with open(filename, 'rb') as f:
        data = f.read()
    # Try different alignments
    for offset in range(width):
        floats_aligned = []
        for i in range(offset, len(data)-width+1, width):
            chunk = data[i:i+width]
            try:
                # 32-bit float
                val = struct.unpack('<f', chunk)[0]
                floats_aligned.append(val)
            except:
                continue
        floats.append((offset, floats_aligned))
    return floats

def floats_to_ascii(float_list):
    out = ''
    for f in float_list:
        if abs(f) < 1e10 and f == f: # exclude NaN/INF/large junk
            c = int(f) & 0xff
            if 32 <= c <= 126:
                out += chr(c)
            else:
                out += '.'
        else:
            out += '.'
    return out

def main():
    filename = sys.argv[1]
    floats = extract_floats(filename, width=4)
    for offset, float_list in floats:
        ascii_text = floats_to_ascii(float_list)
        print(f'Offset {offset}: {ascii_text[:80]}')

if __name__ == '__main__':
    main()

