import struct, string
with open('/home/ctfplayer/ctf_files/floating_points.out', 'rb') as f:
    data = f.read()
results = []
for i in range(0, len(data)-7, 8):
    val = struct.unpack('<d', data[i:i+8])[0]
    b = struct.pack('<d', val)
    if all(chr(x) in string.printable for x in b):
        try:
            results.append(b.decode(errors='replace'))
        except Exception:
            pass
print(''.join(results))

